const RA2WEB_SW_VERSION = config.version;
const RA2WEB_APP_CACHE = 'ra2web-app-' + RA2WEB_SW_VERSION;
const RA2WEB_GAMERES_CACHE = 'ra2web-gameres-' + RA2WEB_SW_VERSION;
const sensitive = new Set(config.updateSensitivePaths);
const runtimeManifestKey = '/__ra2web_runtime_manifest__';

self.addEventListener('install', event => {
  event.waitUntil(caches.open(RA2WEB_APP_CACHE).then(async cache => {
    const dependencies = config.precache.filter(url => config.runtimeVersions?.[new URL(url, self.location.origin).pathname]);
    await Promise.all(dependencies.map(async url => {
      const integrity = config.assetIntegrity[new URL(url, self.location.origin).pathname];
      const request = new Request(url, { integrity });
      const cached = await retainedDependency(request);
      const response = cached || await fetch(request);
      if (!response?.ok || (!cached && !isCacheable(response))) throw new Error('Dependency precache failed: ' + url);
      await cache.put(request, response.clone());
    }));
    await cache.addAll(config.precache.filter(url => !dependencies.includes(url)).map(url => {
      const integrity = config.assetIntegrity[new URL(url, self.location.origin).pathname];
      return new Request(url, { cache: 'reload', ...(integrity ? { integrity } : {}) });
    }));
    await cache.put(runtimeManifestKey, new Response(JSON.stringify({ version: RA2WEB_SW_VERSION, integrity: config.assetIntegrity, runtimeVersions: config.runtimeVersions })));
  }));
});

self.addEventListener('activate', event => {
  event.waitUntil(notifyClients({ type: 'RA2WEB_SW_UPDATE_READY', version: RA2WEB_SW_VERSION }));
});

self.addEventListener('message', event => {
  if (event.data?.type === 'RA2WEB_GET_VERSION') {
    event.ports[0]?.postMessage({ type: 'RA2WEB_SW_VERSION', version: RA2WEB_SW_VERSION, cacheProtocol: 3 });
  } else if (event.data?.type === 'RA2WEB_SKIP_WAITING') {
    event.waitUntil(applyWhenClientsAreReady(event));
  } else if (event.data?.type === 'RA2WEB_GENERATION_BOOTED') {
    event.waitUntil(cleanupOldCaches());
  }
});

async function clientStates() {
  const clients = (await self.clients.matchAll({ includeUncontrolled: true, type: 'window' }))
    .filter(client => !new URL(client.url).pathname.startsWith('/old/'));
  return Promise.all(clients.map(client => new Promise(resolve => {
    const channel = new MessageChannel();
    const finish = state => { clearTimeout(timer); channel.port1.close(); resolve(state); };
    const timer = setTimeout(() => finish(null), 2000);
    channel.port1.onmessage = event => {
      const data = event.data;
      finish(data?.type === 'RA2WEB_CLIENT_STATE' && typeof data.assetVersion === 'string' ? data : null);
    };
    client.postMessage({ type: 'RA2WEB_QUERY_CLIENT_STATE' }, [channel.port2]);
  })));
}

async function applyWhenClientsAreReady(event) {
  const states = await clientStates();
  const applied = states.every(state => state && state.safeToUpdate === true);
  if (applied) await self.skipWaiting();
  event.ports[0]?.postMessage({ type: 'RA2WEB_UPDATE_RESULT', applied });
}

async function cleanupOldCaches() {
  const states = await clientStates();
  // An unresponsive or legacy client may still own a running match. Its cache
  // is not disposable merely because a newer page has finished loading.
  if (states.some(state => !state || !state.cacheVersion)) return;
  const inUse = new Set([RA2WEB_SW_VERSION]);
  for (const state of states) {
    inUse.add(state.assetVersion);
    inUse.add(state.cacheVersion);
  }
  const keys = await caches.keys();
  await Promise.all(keys.filter(key => {
    const match = /^ra2web-(?:app|gameres)-(.+)$/.exec(key);
    return match && !inUse.has(match[1]);
  }).map(key => caches.delete(key)));
}

async function notifyClients(message) {
  for (const client of await self.clients.matchAll({ includeUncontrolled: true, type: 'window' })) client.postMessage(message);
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith('/old/')) return;
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, RA2WEB_APP_CACHE));
  } else if (url.pathname === '/version.json') {
    // A cached manifest cannot establish that a new navigation is current.
    event.respondWith(fetch(new Request(request, { cache: 'no-store' })));
  } else if (url.pathname.startsWith('/res/overlay/') || url.pathname.startsWith('/res/locale/') || sensitive.has(url.pathname)) {
    event.respondWith(networkFirst(request, RA2WEB_APP_CACHE));
  } else if (url.pathname.startsWith('/js/') && /\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9]+$/.test(url.pathname)) {
    // Keep serving already-open fingerprinted clients during this migration.
    event.respondWith(cacheFirst(request, RA2WEB_APP_CACHE, true));
  } else if (url.pathname.startsWith('/js/')) {
    event.respondWith(versionedRuntime(event, url));
  } else if (config.gameResourcePrefixes.some(prefix => url.pathname.startsWith(prefix)) && isVersionedResource(url)) {
    event.respondWith(cacheFirst(request, RA2WEB_GAMERES_CACHE));
  } else if (url.pathname.startsWith('/res/fonts/') || isVersionedResource(url)) {
    event.respondWith(cacheFirst(request, RA2WEB_APP_CACHE));
  }
});

async function networkFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(new Request(request, { cache: 'no-cache' }));
    if (isCacheable(response)) await cache.put(request, response.clone());
    return response;
  } catch (error) {
    const cached = await cache.match(request);
    if (cached) return cached;
    if (request.mode === 'navigate') {
      const index = await cache.match('/index.html');
      if (index) return index;
    }
    throw error;
  }
}

async function versionedRuntime(event, url) {
  const version = url.searchParams.get('v');
  if (!version) {
    const integrity = config.assetIntegrity[url.pathname];
    if (!integrity) return new Response('Runtime request requires a build version', { status: 409 });
    return fetch(new Request(event.request, { cache: 'no-cache', integrity }));
  }
  if (url.pathname === '/js/vendor.js' && /^[a-f0-9]{64}$/.test(version)) return dependencyRuntime(event, url, version);
  const cache = await caches.open('ra2web-app-' + version);
  const cached = await cache.match(event.request);
  if (cached) return cached;
  let integrity;
  if (version === RA2WEB_SW_VERSION) {
    integrity = config.assetIntegrity[url.pathname];
  } else {
    const saved = await cache.match(runtimeManifestKey);
    if (saved) {
      const manifest = await saved.json();
      if (manifest.version === version) integrity = manifest.integrity[url.pathname];
    } else {
      // A newer page may still be controlled by an older SW. Resolve the newer
      // manifest, never substitute the old controller's files or integrity map.
      const response = await fetch('/version.json', { cache: 'no-store' });
      if (!response.ok) return response;
      const manifest = await response.json();
      if (manifest.assetVersion !== version) {
        if (event.clientId) {
          const client = await self.clients.get(event.clientId);
          client?.postMessage({ type: 'RA2WEB_RUNTIME_VERSION_MISMATCH', expected: version, actual: manifest.assetVersion });
        }
        return new Response('Client build changed; reload the page', { status: 409 });
      }
      integrity = manifest.files?.[url.pathname.slice(1)]?.integrity;
    }
  }
  if (!integrity) return new Response('Runtime file is not part of the requested build', { status: 404 });
  const response = await fetchVerifiedRuntime(event, integrity, version);
  if (isCacheable(response)) await cache.put(event.request, response.clone());
  return response;
}

async function fetchVerifiedRuntime(event, integrity, expected) {
  try {
    return await fetch(new Request(event.request, { cache: 'no-cache', integrity }));
  } catch (error) {
    // An evicted old runtime may now resolve to new bytes at its fixed path.
    // SRI must still reject it. Only a fresh manifest can classify the failure
    // as an update rather than an ordinary network/worker error.
    try {
      const response = await fetch('/version.json', { cache: 'no-store' });
      if (response.ok) {
        const manifest = await response.json();
        const path = new URL(event.request.url).pathname.slice(1);
        const actualRuntime = manifest.runtimeVersions?.[path] || manifest.assetVersion;
        if (typeof actualRuntime === 'string' && actualRuntime !== expected &&
            typeof manifest.assetVersion === 'string' && manifest.assetVersion && event.clientId) {
          const client = await self.clients.get(event.clientId);
          client?.postMessage({ type: 'RA2WEB_RUNTIME_VERSION_MISMATCH', expected, actual: manifest.assetVersion });
        }
      }
    } catch (_) {
      // Keep the original integrity/network error; offline is not update proof.
    }
    throw error;
  }
}

async function retainedDependency(request) {
  // Exact URL includes the dependency content version. Reuse across app
  // generations so installation also avoids downloading unchanged libraries.
  for (const name of await caches.keys()) {
    if (!name.startsWith('ra2web-app-')) continue;
    const response = await (await caches.open(name)).match(request);
    if (response) return response;
  }
}

async function dependencyRuntime(event, url, version) {
  const cached = await retainedDependency(event.request);
  if (cached) return cached;
  let integrity;
  if (config.runtimeVersions?.[url.pathname] === version) integrity = config.assetIntegrity[url.pathname];
  else {
    const response = await fetch('/version.json', { cache: 'no-store' });
    if (!response.ok) return response;
    const manifest = await response.json();
    if (manifest.runtimeVersions?.[url.pathname.slice(1)] !== version) {
      const client = event.clientId && await self.clients.get(event.clientId);
      client?.postMessage({ type: 'RA2WEB_RUNTIME_VERSION_MISMATCH', expected: version, actual: manifest.assetVersion });
      return new Response('Dependency changed; reload the page', { status: 409 });
    }
    integrity = manifest.files?.[url.pathname.slice(1)]?.integrity;
  }
  if (!integrity) return new Response('Dependency integrity is missing', { status: 404 });
  const response = await fetchVerifiedRuntime(event, integrity, version);
  if (isCacheable(response)) await (await caches.open(RA2WEB_APP_CACHE)).put(event.request, response.clone());
  return response;
}

async function cacheFirst(request, cacheName, includeRetainedRuntime = false) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;
  // Activation changes the controller of existing pages. Their fingerprinted
  // dependencies still belong to the retained cache of the build they loaded.
  if (includeRetainedRuntime) {
    for (const name of await caches.keys()) {
      if (name === cacheName || !name.startsWith('ra2web-app-')) continue;
      const previous = await (await caches.open(name)).match(request);
      if (previous) return previous;
    }
  }
  const integrity = config.assetIntegrity[new URL(request.url).pathname];
  const response = await fetch(integrity ? new Request(request, { integrity }) : request);
  if (isCacheable(response)) await cache.put(request, response.clone());
  return response;
}

function isCacheable(response) {
  return response && response.ok && (response.type === 'basic' || response.type === 'cors');
}

function isVersionedResource(url) {
  return url.searchParams.has('h') || url.searchParams.has('v');
}
